import{_ as e,o as t,c as r}from"./chunks/framework.CdjpmwdR.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","heroEyebrow":"认知模型","heroTitle":"塑造 # 型认知：","heroTitleHighlight":"AI时代快速成长的核心法则","heroDescription":"跨领域连接与主动探索，是人类在AI时代的核心优势","heroPrimaryButton":"核心洞察","heroSecondaryButton":"# 如何执行","heroSecondaryButtonHref":"/blogs/","structureTitle":"解构 # 型结构","structureDescription":"横线，代表知识的广度；竖线，代表技能的深度。交叉点，即构筑你独特认知的关键节点。","structureCardTitle":"核心概念","structureCardDescription":"跨领域思考，在不确定的环境中提供稳定的决策支点。","insightsTitleLine1":"核心","insightsTitleLine2":"洞察","insightsSubtitle":"从深度重估、主动探索到迁移结构，重新理解AI时代的人类优势","insights":[{"index":"01","title":"深度，正在被重新定价","paragraphs":["过去，我们认为顶尖人才的标准是M型，在2到3个领域都有足够的深度，能独立完成复杂判断，这已经是极少数人才能做到的事。","但AI的出现，正在重新定价这种深度。当前的AI不仅博学，还具备推理能力，上下文窗口越来越大，token成本越来越低。","它可以在几分钟内消化一个领域的核心文献，给出专业级分析与方案。M型人才引以为傲的多领域深度，正在被AI快速平替。"]},{"index":"02","title":"人类的机会，在主动探索","paragraphs":["AI很博学，但它不会主动去探索。它只能在已被训练的知识边界内运作，无法自发提出“我想去一个从未被研究过的方向看看”。","而人类恰恰可以。我们能感知哪里有空白、哪里有张力、哪里值得一试。"],"listItems":["研究：深入未被充分理解的领域，建立新知识","创新：在已有领域内重新组合，产生新解法","迁移：把A领域经验带到B领域尝试，快速产生洞见"]},{"index":"03","title":"# 型认知，是可迁移能力的结构化表达","paragraphs":["MeshShape认知由宽度与深度交织而成。两条横线是跨域宽度，两条竖线是选定方向的深度，交叉点是你能看见别人看不见的地方。","AI可以帮你跑得更快，但你得先知道往哪个方向跑。这个方向感，来自你在多个领域之间建立的连接网络。"]}],"ctaTitle":"人能够构建网络，网络才会链接人。"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function s(a,n,o,c,h,l){return t(),r("div")}const u=e(i,[["render",s]]);export{p as __pageData,u as default};
